#!/usr/bin/env python3
"""Avenue 2 (Track C): the face of a domain cone generated by two non-orthogonal pure products that
share no factor.  Exact checks on one rational instance; the universal statements are written
(report, Avenue 2, nodes C2.1-C2.4) and these checks certify the identities they use.

Requires SymPy (exact symbolic identities).  Self-contained: reads no file.
Run:  <python with sympy> -I face_structure_exact.py

Notation.  Domain: closed convex cones C with SEP <= C <= BP (= maxCone, the block-positive cone) on
Herm(4).  x = |ab><ab|, y = |a'b'><a'b'|, z = x + y, with a != a', b != b' as rays and
<a|a'> != 0, <b|b'> != 0.  p1 = a_perp (x) b'_perp, p2 = a'_perp (x) b_perp.
W = {w Hermitian : <q|w|p_i> = 0 for q in {p_i, gamma_i^perp delta_i, gamma_i delta_i^perp}} where
p_i = gamma_i (x) delta_i.  Coordinates on W:
    w(al, be, ga, de) = al x + be y + ga |ab><a'b'| + conj(ga) |a'b'><ab|
                                     + de |ab'><a'b| + conj(de) |a'b><ab'|.
Instance: a = (1,0), a' = (3,4)/5, b = (1,0), b' = (5,12i)/13.

Checks:
  W6    the ten real conditions have rank 10 on Herm(4), so dim W = 6; the six coordinate
        directions lie in W and are independent: W is exactly the coordinate space.
  ZER   f_z(c,d) = <cd|z|cd> vanishes at p1 and p2 (the only zeros: written, C2.1).
  FW    the polynomial identity f_w(c,d) = al|A B|^2 + be|A'B'|^2 + 2Re(ga A B conj(A' B'))
        + 2Re(de A B' conj(A' B)), A = <c|a>, A' = <c|a'>, B = <d|b>, B' = <d|b'>, in symbolic c, d.
  ZETA  for every complex zeta, c(zeta) = (a - zeta a')_perp has <c|a> = zeta <c|a'> (symbolic
        zeta): the ratios A/A' and B/B' range over all of C, so the bracket alpha r^2 + beta
        - 2(|ga| + |de|) r is attained (written, C2.2): W cap BP = {sqrt(al be) >= |ga| + |de|}.
  NEG   at (al, be, ga, de) = (1, 1, 1/2, 3/5), outside the inequality, the product vector built
        from zeta = -1, xi = 1 gives a strictly negative product expectation (exact).
  QF    the de = 0 slice is the Q3 face: w(al,be,ga,0) has coefficient matrix [[al,ga],[conj ga,be]]
        in the basis {ab, a'b'} (exact), so it is PSD iff al be >= |ga|^2.
  GF    Gamma(|ab'><a'b|) = |a conj(b)><a' conj(b')|: the ga = 0 slice is the Gamma(Q3) face.
  PROD  the only product vectors in span{ab, a'b'} are multiples of ab and a'b': the coefficient
        determinant equals u v s s' with s, s' != 0 (symbolic identity).
  LAM4  the kappa = 1 slice {de = ga} is the cone al be >= 4|ga|^2, a Lorentz cone Lambda_4
        (signature (1,3) of the quadratic form, exact); the real slice {ga real, de = 0} is Lambda_3.
  SEPF  in C = SEP + F the face of z is F (written C2.3); exact part: the products of the face are
        x and y only (by PROD), and z lies in the relative interior of each listed slice.
  DIST  in every super-quantum domain cone (Q3 <= C <= BP) x and y are not perfectly
        distinguishable: an effect E with I - E in C* <= PSD and <ab|E|ab> = 1 has E ab = ab, and
        then <a'b'|E|ab> = <a'b'|ab> != 0 contradicts E a'b' = 0 (exact overlap value).
A mutation self-test runs first; the verdict prints only if every mutation is detected and every
unmutated check passes.
"""
import sys
import sympy as sp

MUT = set()
RESULTS = []


def check(ok, cid, text):
    RESULTS.append((bool(ok), cid, text))


I = sp.I


def ket(*v):
    return sp.Matrix(v)


def kron(u, v):
    return sp.Matrix([u[i] * v[j] for i in range(2) for j in range(2)])


def perp(v):
    return sp.Matrix([-sp.conjugate(v[1]), sp.conjugate(v[0])])


def outer(u, v):
    return u * v.H


def ip(u, v):
    return sp.simplify((u.H * v)[0, 0])


def gamma2(M):
    out = sp.zeros(4, 4)
    for a1 in range(2):
        for a2 in range(2):
            for b1 in range(2):
                for b2 in range(2):
                    out[2 * a1 + a2, 2 * b1 + b2] = M[2 * a1 + b2, 2 * b1 + a2]
    return out


def herm_basis():
    B = []
    for i in range(4):
        for j in range(4):
            M = sp.zeros(4, 4)
            if i == j:
                M[i, i] = 1
            elif i < j:
                M[i, j] = 1
                M[j, i] = 1
            else:
                M[i, j] = I
                M[j, i] = -I
            B.append(M)
    return B


def herm_coords(M):
    v = []
    for i in range(4):
        for j in range(4):
            if i == j:
                v.append(sp.re(M[i, i]))
            elif i < j:
                v.append(sp.re(M[i, j]))
            else:
                v.append(sp.im(M[i, j]))
    return v


def run():
    RESULTS.clear()
    a = ket(1, 0)
    a2 = ket(sp.Rational(3, 5), sp.Rational(4, 5))
    b = ket(1, 0)
    b2 = ket(sp.Rational(5, 13), sp.Rational(12, 13) * I)
    if "shared_factor" in MUT:
        b2 = b
    ab, a2b2, ab2, a2b = kron(a, b), kron(a2, b2), kron(a, b2), kron(a2, b)
    x, y = outer(ab, ab), outer(a2b2, a2b2)
    z = x + y
    p1 = kron(perp(a), perp(b2))
    p2 = kron(perp(a2), perp(b))
    # ---- W6
    conds = []
    for (gm, dl) in [(perp(a), perp(b2)), (perp(a2), perp(b))]:
        p = kron(gm, dl)
        qs = [p, kron(perp(gm), dl), kron(gm, perp(dl))]
        if "drop_condition" in MUT:
            qs = qs[:2]
        for q in qs:
            row = [sp.expand((q.H * M * p)[0, 0]) for M in herm_basis()]
            conds.append([sp.re(r) for r in row])
            conds.append([sp.im(r) for r in row])
    A = sp.Matrix(conds)
    rkc = A.rank()
    dirs = [x, y, outer(ab, a2b2) + outer(a2b2, ab), I * outer(ab, a2b2) - I * outer(a2b2, ab),
            outer(ab2, a2b) + outer(a2b, ab2), I * outer(ab2, a2b) - I * outer(a2b, ab2)]
    in_W = all(all(sp.simplify(e) == 0 for e in A * sp.Matrix(herm_coords(D))) for D in dirs)
    indep = sp.Matrix([herm_coords(D) for D in dirs]).rank() == 6
    check(rkc == 10 and in_W and indep, "W6", f"conditions rank {rkc}, dim W = {16 - rkc}; the six coordinate directions lie in W and are independent")
    # ---- ZER
    fz1 = sp.simplify((p1.H * z * p1)[0, 0])
    fz2 = sp.simplify((p2.H * z * p2)[0, 0])
    check(fz1 == 0 and fz2 == 0, "ZER", "f_z vanishes at p1 = a_perp b'_perp and p2 = a'_perp b_perp")
    # ---- FW (symbolic c, d)
    c0, c1, d0, d1 = sp.symbols("c0 c1 d0 d1")
    al, be = sp.symbols("alpha beta", real=True)
    g1, g2, e1, e2 = sp.symbols("g1 g2 e1 e2", real=True)
    ga, de = g1 + I * g2, e1 + I * e2
    c, d = ket(c0, c1), ket(d0, d1)
    w = al * x + be * y + ga * outer(ab, a2b2) + sp.conjugate(ga) * outer(a2b2, ab) \
        + de * outer(ab2, a2b) + sp.conjugate(de) * outer(a2b, ab2)
    cd = kron(c, d)
    fw = (cd.H * w * cd)[0, 0]
    Ac, A2c = (c.H * a)[0, 0], (c.H * a2)[0, 0]
    Bd, B2d = (d.H * b)[0, 0], (d.H * b2)[0, 0]
    rhs = al * Ac * sp.conjugate(Ac) * Bd * sp.conjugate(Bd) + be * A2c * sp.conjugate(A2c) * B2d * sp.conjugate(B2d) \
        + ga * Ac * Bd * sp.conjugate(A2c * B2d) + sp.conjugate(ga * Ac * Bd) * A2c * B2d \
        + de * Ac * B2d * sp.conjugate(A2c * Bd) + sp.conjugate(de * Ac * B2d) * A2c * Bd
    if "fw_sign" in MUT:
        rhs = rhs - 2 * (de * Ac * B2d * sp.conjugate(A2c * Bd) + sp.conjugate(de * Ac * B2d) * A2c * Bd)
    check(sp.expand(fw - rhs) == 0, "FW", "f_w(c,d) = al|AB|^2 + be|A'B'|^2 + 2Re(ga A B conj(A'B')) + 2Re(de A B' conj(A'B)) as a polynomial identity in symbolic c, d")
    # ---- ZETA
    zr, zi = sp.symbols("zr zi", real=True)
    zeta = zr + I * zi
    cz = perp(a - zeta * a2)
    Az, A2z = sp.expand((cz.H * a)[0, 0]), sp.expand((cz.H * a2)[0, 0])
    ok = sp.expand(Az - zeta * A2z) == 0
    dz = perp(b - zeta * b2)
    Bz, B2z = sp.expand((dz.H * b)[0, 0]), sp.expand((dz.H * b2)[0, 0])
    ok &= sp.expand(Bz - zeta * B2z) == 0
    ok &= sp.simplify(A2z) != 0 and sp.simplify(B2z) != 0
    check(ok, "ZETA", "for symbolic zeta, c = (a - zeta a')_perp gives <c|a> = zeta <c|a'> and d = (b - zeta b')_perp gives <d|b> = zeta <d|b'>, with <c|a'>, <d|b'> not identically zero")
    # ---- NEG
    vals = {al: 1, be: 1, g1: sp.Rational(1, 2), g2: 0, e1: sp.Rational(3, 5), e2: 0}
    zeta0, xi0 = -1, 1
    cw = perp(a - zeta0 * a2)
    dw = perp(b - xi0 * b2)
    cdw = kron(cw, dw)
    wv = w.subs(vals)
    fneg = sp.nsimplify(sp.simplify((cdw.H * wv * cdw)[0, 0]))
    if "neg_inside" in MUT:
        vals2 = dict(vals)
        vals2[e1] = sp.Rational(1, 5)
        fneg = sp.nsimplify(sp.simplify((cdw.H * w.subs(vals2) * cdw)[0, 0]))
    check(fneg.is_real and fneg < 0, "NEG", f"at (al,be,ga,de) = (1,1,1/2,3/5), with sqrt(al be) = 1 < |ga| + |de| = 11/10, the product vector from zeta = -1, xi = 1 gives f_w = {fneg} < 0")
    # ---- QF
    E = sp.Matrix([[al, ga], [sp.conjugate(ga), be]])
    basis = [ab, a2b2]
    wq = sum((E[i, j] * outer(basis[i], basis[j]) for i in range(2) for j in range(2)), sp.zeros(4, 4))
    check(sp.expand(wq - w.subs({e1: 0, e2: 0})) == sp.zeros(4, 4), "QF", "w(al,be,ga,0) = sum_ij M_ij |e_i><e_j| with M = [[al,ga],[conj ga,be]], e = (ab, a'b'): the de = 0 slice is PSD(span{ab, a'b'}) = the Q3 face")
    # ---- GF
    bc, b2c = b.conjugate(), b2.conjugate()
    lhs = gamma2(outer(ab2, a2b))
    rhs2 = outer(kron(a, bc), kron(a2, b2c))
    if "gamma_wrong" in MUT:
        rhs2 = outer(kron(a, b), kron(a2, b2))
    check(sp.expand(lhs - rhs2) == sp.zeros(4, 4) and sp.expand(gamma2(x) - outer(kron(a, bc), kron(a, bc))) == sp.zeros(4, 4),
          "GF", "Gamma(|ab'><a'b|) = |a b*><a' b'*| and Gamma(x) = |a b*><a b*|: the ga = 0 slice is Gamma(PSD(span{a b*, a' b'*})), the Gamma(Q3) face")
    # ---- PROD
    u, v = sp.symbols("u v")
    s_a, s_b = (perp(a).H * a2)[0, 0], (perp(b).H * b2)[0, 0]
    vec = u * ab + v * a2b2
    coef = sp.Matrix([[vec[0], vec[1]], [vec[2], vec[3]]])
    det = sp.expand(coef.det())
    # a = e0, b = e0: det = u v * (a2[1]) * (b2[1])
    target = sp.expand(u * v * a2[1] * b2[1])
    check(sp.expand(det - target) == 0 and a2[1] != 0 and b2[1] != 0, "PROD", f"det of the coefficient matrix of u ab + v a'b' equals u v s s' with s = {a2[1]}, s' = {b2[1]}: a product only if u v = 0")
    # ---- LAM4 and Lambda_3
    # kappa = 1 slice: (al, be, g1, g2) with al be - 4(g1^2 + g2^2) >= 0, al, be >= 0
    Q = sp.Matrix([[0, sp.Rational(1, 2), 0, 0], [sp.Rational(1, 2), 0, 0, 0], [0, 0, -4, 0], [0, 0, 0, -4]])
    ev = Q.eigenvals()
    pos = sum(m for e_, m in ev.items() if e_ > 0)
    negc = sum(m for e_, m in ev.items() if e_ < 0)
    Q3 = sp.Matrix([[0, sp.Rational(1, 2), 0], [sp.Rational(1, 2), 0, 0], [0, 0, -1]])
    ev3 = Q3.eigenvals()
    pos3 = sum(m for e_, m in ev3.items() if e_ > 0)
    neg3 = sum(m for e_, m in ev3.items() if e_ < 0)
    # the kappa = 1 slice lies in W cap BP: sqrt(al be) >= 2|ga| = |ga| + |de|
    check(pos == 1 and negc == 3 and pos3 == 1 and neg3 == 2, "LAM4", "the slice de = ga is {al be >= 4|ga|^2, al, be >= 0}: a quadratic form of signature (1,3), a Lorentz cone Lambda_4 inside W cap BP; the slice {ga real, de = 0} has signature (1,2), a Lambda_3")
    # ---- SEPF (exact part): z in relint of the slices; z = w(1,1,0,0)
    zz = w.subs({al: 1, be: 1, g1: 0, g2: 0, e1: 0, e2: 0})
    check(sp.expand(zz - z) == sp.zeros(4, 4), "SEPF", "z = w(1,1,0,0) lies strictly inside every listed slice (al be = 1 > 0 = |ga| + |de|); with PROD, the products of each slice are x and y")
    # ---- DIST
    ov = sp.simplify((a2b2.H * ab)[0, 0])
    check(ov != 0, "DIST", f"<a'b'|ab> = {ov} != 0: in a super-quantum domain cone (C* <= PSD) no effect separates x from y")


MUTATIONS = {
    "shared_factor": "PROD",
    "drop_condition": "W6",
    "fw_sign": "FW",
    "neg_inside": "NEG",
    "gamma_wrong": "GF",
}


def main():
    global MUT
    detected = {}
    for m, target in MUTATIONS.items():
        MUT = {m}
        try:
            run()
            failed = {cid for ok, cid, _ in RESULTS if not ok}
        except Exception as exc:          # a mutation may break an identity outright
            failed = {target}
            print(f"  (mutation {m} raised {type(exc).__name__})")
        detected[m] = target in failed
        print(f"mutation {m:15s} target {target:5s} {'REJECTED' if detected[m] else 'MUTATION-MISSED'} (failing: {sorted(failed)})")
    MUT = set()
    run()
    for ok, cid, text in RESULTS:
        print(f"{'PASS' if ok else 'FAIL'} {cid}: {text}")
    nfail = sum(1 for ok, _, _ in RESULTS if not ok)
    print(f"checks: {len(RESULTS)}, failures: {nfail}, mutations rejected: {sum(detected.values())}/{len(MUTATIONS)}")
    print(f"sympy {sp.__version__}")
    if nfail == 0 and all(detected.values()):
        print("VERDICT FACE-NOT-DETERMINED-BY-DOMAIN-EXACT")
    else:
        print("VERDICT NOT-ESTABLISHED")
        sys.exit(1)


if __name__ == "__main__":
    main()
